(window.KOTOBA_HK=window.KOTOBA_HK||{})[12]={"n":12,"S":[{"id":"l12a","ti":[[["うさぎ","うさぎ"],["と","と"]],[["かめ","かめ"],["の","の"]],[["競走","きょうそう"]]],"tt":{"az":"Dovşanla tısbağanın yarışı","en":"The Hare and the Tortoise","ru":"Заяц и черепаха"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["森","もり"],["に","に"]],[["うさぎ","うさぎ"],["と","と"]],[["かめ","かめ"],["が","が"]],[["いました","いました","いる",2],["。"],["うさぎ","うさぎ"],["は","は"]],[["足","あし"],["が","が"]],[["速かった","はやかった","速い",0],["です","です"],["が","が"],["、"],["かめ","かめ"],["は","は"]],[["とても","とても"]],[["遅かった","おそかった","遅い",0],["です","です"],["。"],["春","はる"],["の","の"]],[["森","もり"],["は","は"]],[["暖かくて","あたたかくて","暖かい",3],["、"],["静か","しずか"],["でした","でした","です",9],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, bir meşədə dovşanla tısbağa yaşayırdı. Dovşan sürətlə qaçırdı, tısbağa isə çox yavaş idi. Yazda meşə isti və sakit idi.","en":"Once upon a time, a hare and a tortoise lived in a forest. The hare was fast, but the tortoise was very slow. The forest was warm and quiet in spring.","ru":"Давным-давно в лесу жили заяц и черепаха. Заяц бегал быстро, а черепаха была очень медленной. Весной в лесу было тепло и тихо."}},{"t":[[["ある日","あるひ"],["、"],["うさぎ","うさぎ"],["は","は"]],[["みんな","みんな"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["「"],["森","もり"],["の","の"]],[["動物","どうぶつ"],["の","の"]],[["中","なか"],["で","で"],["、"],["だれ","だれ"],["が","が"]],[["いちばん","いちばん"]],[["速い","はやい"],["です","です"],["か","か"],["。"],["もちろん","もちろん"],["、"],["わたし","わたし"],["です","です"],["！"],["」"],["かめ","かめ"],["は","は"]],[["少し","すこし"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Bir gün dovşan hamıdan soruşdu: «Meşədəki heyvanlar arasında ən sürətli kimdir? Əlbəttə, mən!» Tısbağa yüngülcə gülümsədi.","en":"One day, the hare asked everyone, “Who is the fastest animal in the forest? I am, of course!” The tortoise smiled a little.","ru":"Однажды заяц спросил у всех: «Кто среди лесных зверей самый быстрый? Конечно, я!» Черепаха слегка улыбнулась."}},{"t":[[["「"],["で","で"],["は","は"],["、"],["あの","あの"]],[["山","やま"],["の","の"]],[["上","うえ"],["まで","まで"]],[["競走","きょうそう"],["しません","しません","する",6],["か","か"],["」"],["と","と"]],[["かめ","かめ"],["は","は"]],[["言いました","いいました","言う",2],["。"],["山","やま"],["は","は"]],[["近く","ちかく"],["ありませんでした","ありませんでした","ある",4],["。"],["うさぎ","うさぎ"],["は","は"],["「"],["いい","いい"],["です","です"],["よ","よ"],["。"],["きのう","きのう"],["は","は"]],[["暇","ひま"],["じゃありませんでした","じゃありませんでした","じゃ"],["が","が"],["、"],["今日","きょう"],["は","は"]],[["暇","ひま"],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Tısbağa dedi: «Elə isə o dağın başına qədər yarışaq?» Dağ yaxın deyildi. Dovşan cavab verdi: «Olar. Dünən boş vaxtım yox idi, amma bu gün boşam».","en":"“Then shall we race to the top of that mountain?” said the tortoise. The mountain was not close. “All right. I wasn’t free yesterday, but I am today,” answered the hare.","ru":"«Тогда давай устроим забег до вершины той горы», – предложила черепаха. Гора была неблизко. «Хорошо. Вчера я был занят, а сегодня свободен», – ответил заяц."}},{"t":[[["きつね","きつね"],["が","が"]],[["白い","しろい"]],[["旗","はた"],["を","を"]],[["上げました","あげました","上げる",2],["。"],["うさぎ","うさぎ"],["は","は"]],[["かめ","かめ"],["より","より"]],[["ずっと","ずっと"]],[["速くて","はやくて","速い",3],["、"],["すぐ","すぐ"],["に","に"]],[["遠く","とおく"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["かめ","かめ"],["は","は"]],[["大きい","おおきい"]],[["石","いし"],["や","や"]],[["小さい","ちいさい"]],[["石","いし"],["の","の"]],[["横","よこ"],["を","を"],["、"],["ゆっくり","ゆっくり"]],[["歩きました","あるきました","歩く",2],["。"]]],"tr":{"az":"Tülkü ağ bayrağı qaldırdı. Dovşan tısbağadan xeyli sürətli idi və tezliklə uzaqlaşdı. Tısbağa böyük və kiçik daşların yanından yavaş-yavaş keçirdi.","en":"The fox raised a white flag. The hare was much faster than the tortoise and soon went far ahead. The tortoise walked slowly past large and small stones.","ru":"Лиса подняла белый флаг. Заяц был гораздо быстрее черепахи и вскоре убежал далеко вперёд. Черепаха медленно шла мимо больших и маленьких камней."}},{"t":[[["道","みち"],["の","の"]],[["横","よこ"],["に","に"]],[["木","き"],["が","が"]],[["二本","にほん"]],[["ありました","ありました","ある",2],["。"],["「"],["大きい","おおきい"]],[["木","き"],["と","と"]],[["小さい","ちいさい"]],[["木","き"],["と","と"],["、"],["どちら","どちら"],["が","が"]],[["涼しい","すずしい"],["です","です"],["か","か"],["」"],["と","と"]],[["うさぎ","うさぎ"],["は","は"]],[["鳥","とり"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["「"],["大きい","おおきい"]],[["木","き"],["の","の"]],[["ほう","ほう"],["が","が"]],[["涼しい","すずしい"],["です","です"],["よ","よ"],["」"],["と","と"]],[["鳥","とり"],["は","は"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Yolun kənarında iki ağac var idi. Dovşan quşdan soruşdu: «Böyük ağacın altında daha sərindir, yoxsa kiçik ağacın?» Quş cavab verdi: «Böyük ağacın altında daha sərindir».","en":"Two trees stood beside the path. “Which is cooler, the big tree or the small tree?” the hare asked a bird. “It’s cooler under the big tree,” the bird answered.","ru":"У дороги стояли два дерева. «Под каким деревом прохладнее: под большим или под маленьким?» – спросил заяц у птицы. «Под большим прохладнее», – ответила птица."}},{"t":[[["うさぎ","うさぎ"],["は","は"]],[["大きい","おおきい"],["のの","のの"]],[["下","した"],["で","で","だ"]],[["休みました","やすみました","休む",2],["。"],["そこ","そこ"],["は","は"]],[["暑く","あつく","暑い"],["ありませんでした","ありませんでした","ある",4],["から","から"],["、"],["すぐ","すぐ"],["に","に"]],[["寝ました","ねました","寝る",2],["。"],["かめ","かめ"],["は","は"]],[["休みませんでした","やすみませんでした","休む",4],["。"],["昼","ひる"],["の","の"]],[["道","みち"],["は","は"]],[["朝","あさ"],["より","より"]],[["暑かった","あつかった","暑い",0],["です","です"],["が","が"],["、"],["一","いち"],["歩","ほ"],["ずつ","ずつ"]],[["進みました","すすみました","進む",2],["。"]]],"tr":{"az":"Dovşan böyük ağacın altında dincəldi. Orada isti olmadığı üçün tezliklə yuxuya getdi. Tısbağa isə dayanmadı. Günorta yol səhərkindən isti olsa da, addım-addım irəlilədi.","en":"The hare rested under the big one. It was not hot there, so he soon fell asleep. The tortoise did not stop to rest. The path was hotter at noon than in the morning, but he went on one step at a time.","ru":"Заяц устроился под большим деревом. Там было нежарко, и он вскоре уснул. Черепаха не отдыхала. В полдень на дороге было жарче, чем утром, но она продолжала идти шаг за шагом."}},{"t":[[["夕方","ゆうがた"],["、"],["うさぎ","うさぎ"],["は","は"]],[["起きました","おきました","起きる",2],["。"],["かめ","かめ"],["は","は"]],[["もう","もう"]],[["山","やま"],["の","の"]],[["上","うえ"],["の","の"]],[["近く","ちかく"],["に","に"]],[["いました","いました","いる",2],["。"],["うさぎ","うさぎ"],["も","も"]],[["急ぎました","いそぎました","急ぐ",2],["が","が"],["、"],["一番","いちばん"],["は","は"]],[["うさぎ","うさぎ"],["じゃありませんでした","じゃありませんでした","じゃ"],["。"],["小さい","ちいさい"]],[["かめ","かめ"],["が","が"]],[["一番","いちばん"],["でした","でした","です",9],["。"]]],"tr":{"az":"Axşama yaxın dovşan oyandı. Tısbağa artıq dağın zirvəsinə yaxın idi. Dovşan da tələsdi, amma birinci olan o deyildi. Balaca tısbağa birinci olmuşdu.","en":"In the late afternoon, the hare woke up. The tortoise was already near the mountaintop. The hare hurried too, but he was not first. The little tortoise was first.","ru":"Под вечер заяц проснулся. Черепаха уже была почти у вершины. Заяц тоже поспешил, но первым оказался не он. Первой была маленькая черепаха."}},{"t":[[["山","やま"],["の","の"]],[["上","うえ"],["で","で"],["、"],["二匹","にひき"],["は","は"]],[["おにぎり","おにぎり"],["を","を"]],[["食べました","たべました","食べる",2],["。"],["かめ","かめ"],["は","は"]],[["大きい","おおきい"],["の","の"],["を","を"]],[["うさぎ","うさぎ"],["に","に"]],[["あげました","あげました","あげる",2],["。"],["「"],["競走","きょうそう"],["と","と"]],[["昼寝","ひるね"],["と","と"],["、"],["どちら","どちら"],["が","が"]],[["好き","すき"],["です","です"],["か","か"],["」"],["と","と"]],[["かめ","かめ"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["うさぎ","うさぎ"],["は","は"]],[["赤い","あかい"]],[["顔","かお"],["で","で"],["「"],["今","いま"],["は","は"]],[["おにぎり","おにぎり"],["が","が"]],[["いちばん","いちばん"]],[["好き","すき"],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Dağın başında ikisi onigiri yedilər. Tısbağa böyüyünü dovşana verdi. Tısbağa soruşdu: «Yarışmağı daha çox sevirsən, yoxsa gündüz yatmağı?» Dovşan üzü qızararaq cavab verdi: «İndi ən çox onigirini sevirəm».","en":"At the top of the mountain, they ate rice balls. The tortoise gave the big one to the hare. “Which do you like better, racing or taking naps?” the tortoise asked. With a red face, the hare answered, “Right now, I like rice balls best.”","ru":"На вершине они поели рисовых колобков. Черепаха отдала зайцу большой. «Что ты больше любишь: соревноваться или спать днём?» – спросила она. Покраснев, заяц ответил: «Сейчас я больше всего люблю рисовые колобки»."}}]},{"id":"l12b","ti":[[["最後","さいご"],["の","の"]],[["バトン","バトン"]]],"tt":{"az":"Son estafet çubuğu","en":"The Final Baton","ru":"Последняя эстафетная палочка"},"P":[{"t":[[["秋","あき"],["の","の"]],[["朝","あさ"],["、"],["小さな","ちいさな"]],[["学校","がっこう"],["で","で","だ"]],[["運動","うんどう"],["会","かい"],["が","が"]],[["ありました","ありました","ある",2],["。"],["きのう","きのう"],["の","の"]],[["天気","てんき"],["は","は"]],[["雨","あめ"],["でした","でした","です",9],["が","が"],["、"],["今日","きょう"],["は","は"]],[["晴れ","はれ"],["でした","でした","です",9],["。"],["校庭","こうてい"],["は","は"]],[["にぎやか","にぎやか"],["で","で","だ"],["、"],["風","かぜ"],["は","は"]],[["涼しかった","すずしかった","涼しい",0],["です","です"],["。"]]],"tr":{"az":"Bir payız səhəri balaca bir məktəbdə idman bayramı keçirildi. Dünən hava yağışlı idi, bu gün isə günəşli idi. Məktəbin həyəti səs-küylü, külək isə sərin idi.","en":"One autumn morning, a small school held a sports festival. It had been rainy yesterday, but today was sunny. The schoolyard was lively, and the breeze was cool.","ru":"Осенним утром в маленькой школе проходил спортивный праздник. Вчера шёл дождь, а сегодня было солнечно. Во дворе было оживлённо, и дул прохладный ветер."}},{"t":[[["赤組","あかぐみ"],["の","の"]],[["レン","レン"],["と","と"]],[["白組","しろぐみ"],["の","の"]],[["ソラ","ソラ"],["は","は"],["、"],["いつ","いつ"],["も","も"]],[["ライバル","ライバル"],["でした","でした","です",9],["。"],["去年","きょねん"],["は","は"]],[["ソラ","ソラ"],["の","の"]],[["ほう","ほう"],["が","が"]],[["速かった","はやかった","速い",0],["です","です"],["。"],["でも","でも"],["、"],["今年","ことし"],["の","の"]],[["レン","レン"],["は","は"]],[["去年","きょねん"],["より","より"]],[["速くて","はやくて","速い",3],["、"],["毎朝","まいあさ"],["の","の"]],[["練習","れんしゅう"],["も","も"]],[["好き","すき"],["でした","でした","です",9],["。"]]],"tr":{"az":"Qırmızı komandadan Renlə ağ komandadan Sora həmişə rəqib idilər. Keçən il Sora daha sürətli idi. Amma bu il Ren əvvəlkindən sürətli idi və hər səhər məşq etməyi də sevirdi.","en":"Ren from the red team and Sora from the white team were always rivals. Last year, Sora had been faster. But this year, Ren was faster than before, and he enjoyed his morning practice.","ru":"Рэн из красной команды и Сора из белой всегда соперничали. В прошлом году Сора был быстрее. Но в этом году Рэн стал быстрее, чем прежде, и любил утренние тренировки."}},{"t":[[["リレー","リレー"],["の","の"]],[["前","まえ"],["に","に"],["、"],["小さい","ちいさい"]],[["子","こ"],["が","が"]],[["二人","ふたり"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["「"],["レンさん","レンさん"],["と","と"]],[["ソラさん","ソラさん"],["と","と"],["、"],["どちら","どちら"],["が","が"]],[["速い","はやい"],["です","です"],["か","か"],["。"],["」"],["二人","ふたり"],["は","は"]],[["一緒","いっしょ"],["に","に"],["「"],["ぼく","ぼく"],["の","の"]],[["ほう","ほう"],["が","が"]],[["速い","はやい"],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["小さい","ちいさい"]],[["子","こ"],["は","は"]],[["困りました","こまりました","困る",2],["。"]]],"tr":{"az":"Estafetdən əvvəl balaca bir uşaq onlardan soruşdu: «Renlə Soradan hansı daha sürətlidir?» İkisi də eyni anda cavab verdi: «Mən daha sürətliyəm». Balaca uşaq çaşıb qaldı.","en":"Before the relay, a little child asked them, “Who is faster, Ren or Sora?” Both answered together, “I’m faster.” The little child was puzzled.","ru":"Перед эстафетой малыш спросил у них: «Кто быстрее, Рэн или Сора?» Оба одновременно ответили: «Я быстрее». Малыш растерялся."}},{"t":[[["先生","せんせい"],["は","は"]],[["箱","はこ"],["から","から"]],[["バトン","バトン"],["を","を"]],[["二本","にほん"]],[["出しました","だしました","出す",2],["。"],["一本","いっぽん"],["は","は"]],[["太くて","ふとくて","太い",3],["、"],["もう","もう"]],[["一本","いっぽん"],["は","は"]],[["細かった","ほそかった","細い",0],["です","です"],["。"],["レン","レン"],["は","は"]],[["軽い","かるい"],["の","の"],["を","を"]],[["選びました","えらびました","選ぶ",2],["が","が"],["、"],["ソラ","ソラ"],["の","の"],["も","も"]],[["同じ","おなじ"]],[["重さ","おもさ"],["でした","でした","です",9],["。"],["二人","ふたり"],["は","は"]],[["顔","かお"],["を","を"]],[["見て","みて","見る",3],["、"],["少し","すこし"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Müəllim qutudan iki estafet çubuğu çıxardı. Biri qalın, digəri nazik idi. Ren yüngül olanı seçdi, amma Soranınkı da eyni çəkidə idi. İkisi bir-birinə baxıb yüngülcə gülümsədilər.","en":"The teacher took two batons out of a box. One was thick, and the other was thin. Ren chose a light one, but Sora’s weighed just as much. They looked at each other and smiled a little.","ru":"Учитель достал из коробки две эстафетные палочки. Одна была толстой, другая тонкой. Рэн выбрал лёгкую, но палочка Соры весила столько же. Они посмотрели друг на друга и слегка улыбнулись."}},{"t":[[["いよいよ","いよいよ"]],[["リレー","リレー"],["が","が"]],[["始まりました","はじまりました","始まる",2],["。"],["レン","レン"],["と","と"]],[["ソラ","ソラ"],["は","は"]],[["最後","さいご"],["の","の"]],[["走者","そうしゃ"],["でした","でした","です",9],["。"],["「"],["赤組","あかぐみ"],["の","の"]],[["中","なか"],["で","で"],["、"],["だれ","だれ"],["が","が"]],[["いちばん","いちばん"]],[["速い","はやい"],["です","です"],["か","か"],["」"],["と","と"]],[["あの","あの"]],[["子","こ"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["みんな","みんな"],["は","は"],["「"],["レン","レン"],["！"],["」"],["と","と"]],[["大きい","おおきい"]],[["声","こえ"],["で","で","だ"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Nəhayət, estafet başladı. Renlə Sora sonuncu qaçışçılar idi. Həmin uşaq soruşdu: «Qırmızı komandada ən sürətli kimdir?» Hamı ucadan «Ren!» deyə cavab verdi.","en":"At last, the relay began. Ren and Sora were the final runners. “Who is the fastest on the red team?” asked the same child. Everyone shouted, “Ren!”","ru":"Наконец эстафета началась. Рэн и Сора бежали последними. «Кто в красной команде самый быстрый?» – спросил тот самый малыш. Все громко ответили: «Рэн!»"}},{"t":[[["白組","しろぐみ"],["は","は"]],[["赤組","あかぐみ"],["より","より"]],[["少し","すこし"]],[["早く","はやく","早い"]],[["最後","さいご"],["の","の"]],[["一","いち"],["周","しゅう"],["に","に"]],[["入りました","はいりました","入る",2],["。"],["でも","でも"],["、"],["ソラ","ソラ"],["の","の"]],[["前","まえ"],["の","の"]],[["走者","そうしゃ"],["が","が"]],[["転びました","ころびました","転ぶ",2],["。"],["バトン","バトン"],["は","は"]],[["ソラ","ソラ"],["の","の"]],[["足","あし"],["の","の"]],[["前","まえ"],["に","に"]],[["落ちました","おちました","落ちる",2],["。"],["ソラ","ソラ"],["は","は"]],[["バトン","バトン"],["より","より"]],[["先","さき"],["に","に"],["、"],["その","その"]],[["子","こ"],["の","の"]],[["手","て"],["を","を"]],[["取りました","とりました","取る",2],["。"]]],"tr":{"az":"Ağ komanda son dövrəyə qırmızı komandadan bir az tez başladı. Amma Soradan əvvəlki qaçışçı yıxıldı. Çubuq Soranın ayaqlarının qabağına düşdü. Sora çubuğu götürməzdən əvvəl uşağın əlindən tutdu.","en":"The white team reached the final lap a little before the red team. But the runner before Sora fell. The baton dropped at Sora’s feet. Before picking it up, Sora took the child’s hand.","ru":"Белая команда вышла на последний круг чуть раньше красной. Но бегун перед Сорой упал. Палочка оказалась у ног Соры. Прежде чем поднять её, Сора взял ребёнка за руку."}},{"t":[[["レン","レン"],["は","は"]],[["先","さき"],["に","に"]],[["ゴール","ゴール"],["しました","しました","する",2],["が","が"],["、"],["すぐ","すぐ"],["に","に"]],[["ソラ","ソラ"],["の","の"]],[["所","ところ"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["あの","あの"]],[["子","こ"],["の","の"]],[["けが","けが"],["は","は"]],[["ひどく","ひどく","ひどい"],["ありませんでした","ありませんでした","ある",4],["。"],["ソラ","ソラ"],["は","は"]],[["一番","いちばん"],["じゃありませんでした","じゃありませんでした","じゃ"],["が","が"],["、"],["みんな","みんな"],["の","の"]],[["拍手","はくしゅ"],["は","は"]],[["レン","レン"],["の","の"]],[["時","とき"],["より","より"]],[["大きかった","おおきかった","大きい",0],["です","です"],["。"]]],"tr":{"az":"Ren finişə birinci çatdı, amma dərhal Soranın yanına getdi. Uşağın zədəsi ağır deyildi. Sora birinci olmamışdı, amma hamı onu Rendən də gur alqışladı.","en":"Ren finished first, but he went straight over to Sora. The child’s injury was not serious. Sora had not come first, but the applause for him was louder than it had been for Ren.","ru":"Рэн первым пересёк финиш, но сразу подошёл к Соре. Ребёнок ушибся несильно. Сора не стал первым, зато ему хлопали громче, чем Рэну."}},{"t":[[["帰り","かえり"],["に","に"],["、"],["小さい","ちいさい"]],[["子","こ"],["が","が"]],[["また","また"]],[["二人","ふたり"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["「"],["学校","がっこう"],["で","で","だ"]],[["だれ","だれ"],["が","が"]],[["いちばん","いちばん"]],[["強い","つよい"],["です","です"],["か","か"],["。"],["」"],["レン","レン"],["は","は"]],[["ソラ","ソラ"],["を","を"],["、"],["ソラ","ソラ"],["は","は"]],[["レン","レン"],["を","を"]],[["指しました","さしました","指す",2],["。"],["今度","こんど"],["は","は"]],[["答え","こたえ"],["が","が"]],[["違いました","ちがいました","違う",2],["が","が"],["、"],["二人","ふたり"],["は","は"]],[["朝","あさ"],["より","より"]],[["うれし","うれし","うれしい"],["そう","そう"],["でした","でした","です",9],["。"]]],"tr":{"az":"Evə qayıdarkən balaca uşaq onlardan yenə soruşdu: «Məktəbdə ən güclü kimdir?» Ren Soranı, Sora isə Reni göstərdi. Bu dəfə cavabları fərqli idi, amma ikisi də səhərkindən daha sevincli görünürdü.","en":"On the way home, the little child asked them again, “Who is the strongest in the school?” Ren pointed to Sora, and Sora pointed to Ren. This time their answers were different, but both looked happier than they had that morning.","ru":"По дороге домой малыш снова спросил: «Кто в школе самый сильный?» Рэн указал на Сору, а Сора на Рэна. На этот раз ответы были разными, но оба выглядели счастливее, чем утром."}}]},{"id":"l12c","ti":[[["いちばん","いちばん"]],[["よかった","よかった","よい",0]],[["場所","ばしょ"]]],"tt":{"az":"Ən gözəl yer","en":"The Best Place","ru":"Самое лучшее место"},"P":[{"t":[[["日曜","にちよう"],["日","ひ"],["の","の"]],[["朝","あさ"],["、"],["ミナ","ミナ"],["は","は"]],[["家族","かぞく"],["と","と"]],[["旅行","りょこう"],["から","から"]],[["帰りました","かえりました","帰る",2],["。"],["海","うみ"],["の","の"]],[["近く","ちかく"],["の","の"]],[["ホテル","ホテル"],["に","に"]],[["二","に"],["泊","はく"],["しました","しました","する",2],["。"],["ホテル","ホテル"],["は","は"]],[["きれい","きれい"],["でした","でした","です",9],["が","が"],["、"],["部屋","へや"],["は","は"]],[["あまり","あまり"]],[["静か","しずか"],["じゃありませんでした","じゃありませんでした","じゃ"],["。"]]],"tr":{"az":"Bazar günü səhər Mina ailəsi ilə səyahətdən qayıtdı. Onlar dəniz yaxınlığındakı bir hoteldə iki gecə qalmışdılar. Hotel gözəl idi, amma otaq o qədər də sakit deyildi.","en":"On Sunday morning, Mina returned from a trip with her family. They had spent two nights at a hotel near the sea. The hotel was lovely, but their room was not very quiet.","ru":"В воскресенье утром Мина вернулась из поездки с семьёй. Они провели две ночи в отеле возле моря. Отель был красивым, но в комнате было не очень тихо."}},{"t":[[["午後","ごご"],["、"],["おばあさん","おばあさん"],["が","が"]],[["家","いえ"],["に","に"]],[["来ました","きました","来る",2],["。"],["「"],["旅行","りょこう"],["は","は"]],[["どう","どう"],["でした","でした","です",9],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["ミナ","ミナ"],["は","は"],["「"],["楽しかった","たのしかった","楽しい",0],["です","です"],["。"],["でも","でも"],["、"],["海","うみ"],["の","の"]],[["水","みず"],["は","は"]],[["冷たかった","つめたかった","冷たい",0],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Günortadan sonra nənəsi onlara gəldi. «Səyahət necə keçdi?» deyə soruşdu. Mina cavab verdi: «Əyləncəli idi. Amma dənizin suyu soyuq idi».","en":"In the afternoon, her grandmother came to visit. “How was your trip?” she asked. “It was fun. But the seawater was cold,” Mina answered.","ru":"После обеда в гости пришла бабушка. «Как прошла поездка?» – спросила она. «Было весело. Но вода в море была холодная», – ответила Мина."}},{"t":[[["お父さん","おとうさん"],["は","は"]],[["かばん","かばん"],["から","から"]],[["写真","しゃしん"],["を","を"]],[["出しました","だしました","出す",2],["。"],["「"],["ホテル","ホテル"],["と","と"]],[["家","いえ"],["と","と"],["、"],["どちら","どちら"],["が","が"]],[["よかった","よかった","よい",0],["です","です"],["か","か"],["」"],["と","と"]],[["おばあさん","おばあさん"],["は","は"]],[["聞きました","ききました","聞く",2],["。"],["お父さん","おとうさん"],["は","は"],["「"],["ホテル","ホテル"],["の","の"]],[["ほう","ほう"],["が","が"]],[["よかった","よかった","よい",0],["です","です"],["。"],["朝ご飯","あさごはん"],["が","が"]],[["とても","とても"]],[["おいしかった","おいしかった","おいしい",0],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Atası çantadan şəkilləri çıxardı. Nənəsi soruşdu: «Hoteldə daha yaxşı idi, yoxsa evdə?» Atası cavab verdi: «Hoteldə daha yaxşı idi. Səhər yeməyi çox dadlı idi».","en":"Her father took some photos out of his bag. “Which was better, the hotel or home?” her grandmother asked. “The hotel was better. The breakfast was delicious,” her father answered.","ru":"Папа достал из сумки фотографии. «Где было лучше: в отеле или дома?» – спросила бабушка. «В отеле было лучше. Завтрак был очень вкусный», – ответил папа."}},{"t":[[["お母さん","おかあさん"],["は","は"]],[["海","うみ"],["の","の"]],[["写真","しゃしん"],["を","を"]],[["選びました","えらびました","選ぶ",2],["。"],["「"],["海","うみ"],["は","は"]],[["町","まち"],["より","より"]],[["涼しかった","すずしかった","涼しい",0],["です","です"],["。"],["空港","くうこう"],["も","も"]],[["ホテル","ホテル"],["から","から"]],[["近くて","ちかくて","近い",3],["、"],["便利","べんり"],["でした","でした","です",9],["。"],["」"],["でも","でも"],["、"],["ミナ","ミナ"],["は","は"]],[["写真","しゃしん"],["を","を"]],[["一枚","いちまい"],["も","も"]],[["選びませんでした","えらびませんでした","選ぶ",4],["。"]]],"tr":{"az":"Anası dəniz şəklini seçdi. «Dəniz kənarı şəhərdən daha sərin idi. Hava limanı da hotelə yaxın idi, rahat idi». Amma Mina heç bir şəkil seçmədi.","en":"Her mother chose a photo of the sea. “It was cooler by the sea than in town. The airport was close to the hotel too, which was convenient.” But Mina did not choose a single photo.","ru":"Мама выбрала фотографию моря. «У моря было прохладнее, чем в городе. Аэропорт тоже находился близко к отелю, это было удобно». Но Мина не выбрала ни одной фотографии."}},{"t":[[["「"],["旅行","りょこう"],["で","で","だ"]],[["どこ","どこ"],["が","が"]],[["いちばん","いちばん"]],[["よかった","よかった","よい",0],["です","です"],["か","か"],["」"],["と","と"]],[["おばあさん","おばあさん"],["は","は"]],[["ミナ","ミナ"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["ミナ","ミナ"],["は","は"]],[["少し","すこし"]],[["考えました","かんがえました","考える",2],["。"],["「"],["狭い","せまい"]],[["所","ところ"],["です","です"],["。"],["ホテル","ホテル"],["より","より"]],[["狭かった","せまかった","狭い",0],["です","です"],["が","が"],["、"],["寂しく","さびしく","寂しい"],["ありませんでした","ありませんでした","ある",4],["。"],["」"]]],"tr":{"az":"Nənəsi Minadan soruşdu: «Səyahətdə ən çox hansı yeri bəyəndin?» Mina bir az düşündü. «Dar bir yeri. Hoteldən daha dar idi, amma orada özümü tənha hiss etmirdim».","en":"“Which place did you like best on the trip?” her grandmother asked Mina. Mina thought for a moment. “A small place. It was smaller than the hotel, but I didn’t feel lonely there.”","ru":"«Какое место в поездке тебе понравилось больше всего?» – спросила бабушка у Мины. Мина немного подумала. «Одно тесное место. Там было теснее, чем в отеле, но мне не было одиноко»."}},{"t":[[["お父さん","おとうさん"],["は","は"]],[["バス","バス"],["の","の"]],[["写真","しゃしん"],["を","を"]],[["見せました","みせました","見せる",2],["。"],["「"],["この","この"]],[["大きい","おおきい"]],[["バス","バス"],["です","です"],["か","か"],["。"],["それ","それ"],["と","と"],["も","も"],["、"],["小さい","ちいさい"],["の","の"],["です","です"],["か","か"],["。"],["」"],["ミナ","ミナ"],["は","は"]],[["首","くび"],["を","を"]],[["横","よこ"],["に","に"]],[["振りました","ふりました","振る",2],["。"],["「"],["バス","バス"],["じゃありません","じゃありません","じゃ"],["。"],["お金","おかね"],["も","も"]],[["かかりませんでした","かかりませんでした","かかる",4],["。"],["」"]]],"tr":{"az":"Atası avtobus şəklini göstərdi. «Bu böyük avtobusdur? Yoxsa kiçiyi?» Mina başını buladı. «Avtobus deyil. Orada pul da lazım olmadı».","en":"Her father showed her a photo of a bus. “Was it this big bus? Or a small one?” Mina shook her head. “It wasn’t a bus. It didn’t cost any money either.”","ru":"Папа показал фотографию автобуса. «Этот большой автобус? Или маленький?» Мина покачала головой. «Это был не автобус. И денег платить не пришлось»."}},{"t":[[["ミナ","ミナ"],["は","は"]],[["お母さん","おかあさん"],["の","の"]],[["赤い","あかい"]],[["傘","かさ"],["を","を"]],[["指しました","さしました","指す",2],["。"],["旅行","りょこう"],["の","の"]],[["二日目","ふつかめ"],["は","は"]],[["雨","あめ"],["で","で","だ"],["、"],["三人","さんにん"],["は","は"]],[["その","その"]],[["傘","かさ"],["の","の"]],[["下","した"],["に","に"]],[["入りました","はいりました","入る",2],["。"],["「"],["あそこ","あそこ"],["が","が"]],[["いちばん","いちばん"]],[["よかった","よかった","よい",0],["です","です"],["。"],["お父さん","おとうさん"],["も","も"]],[["お母さん","おかあさん"],["も","も"],["、"],["いつ","いつ"],["も","も"],["より","より"]],[["近かった","ちかかった","近い",0],["です","です"],["。"],["」"]]],"tr":{"az":"Mina anasının qırmızı çətirini göstərdi. Səyahətin ikinci günü yağış yağmışdı və üçü də həmin çətirin altına girmişdilər. «Ən gözəl yer ora idi. Atam da, anam da həmişəkindən daha yaxınımda idi».","en":"Mina pointed to her mother’s red umbrella. It had rained on the second day, and all three had stood under it. “That was the best place. Dad and Mum were both closer to me than usual.”","ru":"Мина указала на мамин красный зонт. Во второй день поездки шёл дождь, и все трое спрятались под ним. «Там было лучше всего. И папа, и мама были ближе ко мне, чем обычно»."}},{"t":[[["お父さん","おとうさん"],["も","も"]],[["お母さん","おかあさん"],["も","も"],["、"],["ミナ","ミナ"],["の","の"]],[["隣","となり"],["に","に"]],[["座りました","すわりました","座る",2],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["今日","きょう"],["は","は"]],[["傘","かさ"],["が","が"]],[["ありません","ありません","ある",6],["が","が"],["、"],["近い","ちかい"],["です","です"],["ね","ね"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"],["外","そと"],["は","は"]],[["曇り","くもり"],["でした","でした","です",9],["が","が"],["、"],["ミナ","ミナ"],["の","の"]],[["心","こころ"],["は","は"]],[["春","はる"],["より","より"]],[["暖かかった","あたたかかった","暖かい",0],["です","です"],["。"]]],"tr":{"az":"Atası da, anası da Minanın yanında oturdular. Nənəsi gülümsədi: «Bu gün çətir yoxdur, amma yenə bir-birinizə yaxınsınız». Çöldə hava buludlu idi, amma Minanın ürəyi yazdan da isti idi.","en":"Her father and mother both sat down beside Mina. “There’s no umbrella today, but you’re still close together,” her grandmother said with a smile. Outside, the sky was cloudy, but Mina’s heart felt warmer than spring.","ru":"Папа и мама сели рядом с Миной. «Сегодня зонта нет, а вы всё равно рядом», – с улыбкой сказала бабушка. За окном было пасмурно, но на душе у Мины было теплее, чем весной."}}]}],"G":{"あげる":{"b":"あげる","p":"v","m":{"az":"vermək, hədiyyə etmək","en":"give","ru":"давать, дарить"},"n":{"az":"Alan şəxs に, verilən şey を ilə işlənir: 友達に本をあげる; danışana verilən şey üçün adətən くれる işlənir.","en":"The recipient takes に and the gift を, as in 友達に本をあげる; giving to the speaker is usually expressed with くれる.","ru":"Получатель обозначается с に, подарок с を: 友達に本をあげる; когда дают говорящему, обычно используется くれる."}},"あそこ":{"b":"あそこ","p":"pr","m":{"az":"ora; orada","en":"over there; that place","ru":"там; то место"},"n":{"az":"Həm danışandan, həm də dinləyəndən uzaq yeri bildirir.","en":"Refers to a place far from both speaker and listener.","ru":"Указывает на место, удалённое и от говорящего, и от слушающего."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"あまり":{"b":"あまり","p":"ad","m":{"az":"o qədər də, çox da","en":"not very, not much","ru":"не очень, не особо"},"n":{"az":"Adətən inkarla işlənir: あまり寒くない = o qədər də soyuq deyil.","en":"Usually used with a negative: あまり寒くない = not very cold.","ru":"Обычно используется с отрицанием: あまり寒くない = не очень холодно."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いちばん":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən, birinci","en":"most, number one","ru":"самый, на первом месте"},"n":{"az":"Sifətlə üstünlük dərəcəsi yaradır: いちばん大きい - ən böyük.","en":"Forms a superlative with adjectives: いちばん大きい means the biggest.","ru":"Образует превосходную степень с прилагательными: いちばん大きい - самый большой."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いよいよ":{"b":"いよいよ","p":"ad","m":{"az":"nəhayət, artıq vaxtı çatdı","en":"at last, finally","ru":"наконец, вот-вот"},"n":{"az":"Çoxdan gözlənilən hadisənin yaxınlaşdığını və ya başladığını bildirir.","en":"Indicates that a long-awaited event is finally approaching or beginning.","ru":"Показывает, что долгожданное событие наконец приближается или начинается."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うさぎ":{"b":"うさぎ","p":"n","m":{"az":"dovşan","en":"rabbit","ru":"кролик, заяц"}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"おいしい":{"b":"おいしい","p":"ai","m":{"az":"dadlı","en":"delicious, tasty","ru":"вкусный"},"n":{"az":"い-sifətdir: おいしくない = dadlı deyil.","en":"An i-adjective: おいしくない = not tasty.","ru":"Прилагательное на い: おいしくない = невкусный."}},"おにぎり":{"b":"おにぎり","p":"n","m":{"az":"düyü topası, onigiri","en":"rice ball, onigiri","ru":"онигири, рисовый шарик"}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お父さん":{"b":"お父さん (おとうさん)","p":"n","m":{"az":"ata","en":"father; dad","ru":"папа; отец"},"n":{"az":"Ataya müraciətdə və başqasının atası haqqında işlənir; kənar şəxslərə öz atandan danışarkən adətən 父 deyilir.","en":"Used to address your father or refer to someone else's; use 父 for your own father when speaking to outsiders.","ru":"Используется при обращении к папе или о чужом отце; о своём отце посторонним обычно говорят 父."}},"お金":{"b":"お金 (おかね)","p":"n","m":{"az":"pul","en":"money","ru":"деньги"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かかる":{"b":"掛かる (かかる)","p":"v","m":{"az":"vaxt və ya pul tələb etmək; ilişmək","en":"take time or money; get caught","ru":"занимать время; попадаться"},"n":{"az":"Mənası birləşmədən asılıdır: 時間がかかる vaxt aparmaq, わなにかかる tələyə düşməkdir.","en":"Meaning depends on the phrase: 時間がかかる means take time; わなにかかる means get caught in a trap.","ru":"Значение зависит от сочетания: 時間がかかる значит занимать время, わなにかかる попасть в ловушку."}},"かばん":{"b":"鞄 (かばん)","p":"n","m":{"az":"çanta","en":"bag","ru":"сумка"}},"かめ":{"b":"亀 (かめ)","p":"n","m":{"az":"tısbağa","en":"turtle, tortoise","ru":"черепаха"}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きつね":{"b":"狐 (きつね)","p":"n","m":{"az":"tülkü","en":"fox","ru":"лиса"}},"きのう":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"けが":{"b":"怪我 (けが)","p":"n","m":{"az":"zədə, xəsarət","en":"injury","ru":"травма"},"n":{"az":"けがをする - zədələnmək.","en":"けがをする means to get injured.","ru":"けがをする означает получить травму."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"じゃ":{"b":"じゃ (← では)","p":"cp","m":{"az":"inkarın birinci hissəsi","en":"first part of the negative","ru":"первая часть отрицания"},"n":{"az":"じゃ ありません birlikdə 'deyil' deməkdir: 学生じゃ ありません = tələbə deyiləm. Rəsmi yazıda では ありません.","en":"じゃ ありません together means 'is not': 学生じゃ ありません = I am not a student. Formal writing: では ありません.","ru":"じゃ ありません вместе = 'не является': 学生じゃ ありません = я не студент. В официальной речи では ありません."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずっと":{"b":"ずっと","p":"ad","m":{"az":"bütün müddət ərzində, daim, xeyli","en":"all along, continuously, much","ru":"всё время, постоянно, намного"},"n":{"az":"Müqayisədə xeyli mənası verir: ずっと大きい.","en":"In comparisons it means much: ずっと大きい.","ru":"При сравнении означает намного: ずっと大きい."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だれ":{"b":"だれ","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"Sual sözü: あの人はだれですか = O adam kimdir? Daha nəzakətli forması どなた.","en":"Question word: あの人はだれですか = Who is that person? More polite: どなた.","ru":"Вопросительное слово: あの人はだれですか = Кто этот человек? Вежливее: どなた."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"どこ":{"b":"どこ","p":"pr","m":{"az":"hara","en":"where","ru":"где, куда"},"n":{"az":"どこの国 = hansı ölkə.","en":"どこの国 = which country.","ru":"どこの国 = какая страна."}},"どちら":{"b":"どちら","p":"pr","m":{"az":"hara, hansı tərəf","en":"where, which way","ru":"где, в какую сторону"},"n":{"az":"Nəzakətli “hara/harada” sualıdır və iki seçim arasında “hansı” mənasında da işlənir.","en":"A polite way to ask “where”; it also means “which” of two choices.","ru":"Вежливый вариант вопроса «где/куда»; также означает «который» из двух."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にぎやか":{"b":"にぎやか (賑やか)","p":"an","m":{"az":"qələbəlik, canlı, səs-küylü","en":"lively, bustling","ru":"оживлённый, многолюдный"},"n":{"az":"な-sifətdir: にぎやかな町 = canlı şəhər.","en":"A na-adjective: にぎやかな町 = lively town.","ru":"な-прилагательное: にぎやかな町 = оживлённый город."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"のの":{"b":"のの","p":"n","m":{"az":"Nono (ad)","en":"Nono (name)","ru":"Ноно (имя)"},"n":{"az":"Ad kimi işlənir; kontekstdə のの ayrıca qrammatik hissələr də ola bilər.","en":"Used as a name; のの can also represent separate grammatical elements in context.","ru":"Используется как имя; のの также может состоять из отдельных грамматических элементов."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひどい":{"b":"ひどい (ひどい)","p":"ai","m":{"az":"dəhşətli, çox pis, ağır","en":"terrible, severe, awful","ru":"ужасный, сильный, тяжёлый"},"n":{"az":"い-sifətdir; ひどく zərf formasıdır.","en":"An i-adjective; ひどく is its adverbial form.","ru":"Это i-прилагательное; ひどく является наречной формой."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほう":{"b":"方 (ほう)","p":"n","m":{"az":"tərəf, istiqamət, seçim","en":"side, direction, option","ru":"сторона, направление, вариант"},"n":{"az":"〜のほう müqayisədə üstün tutulan tərəfi bildirə bilər.","en":"〜のほう can indicate the preferred side in a comparison.","ru":"〜のほう может указывать на предпочтительный вариант при сравнении."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もちろん":{"b":"もちろん","p":"ad","m":{"az":"əlbəttə, şübhəsiz","en":"of course, certainly","ru":"конечно, разумеется"}},"や":{"b":"や","p":"pt","m":{"az":"və, ... kimi","en":"and, things such as","ru":"и, например"},"n":{"az":"や tam olmayan siyahı yaradır: 犬や猫（など）; nida və çağırışda da işlənir: おや、太郎や.","en":"や gives a non-exhaustive list, 犬や猫（など）, and also appears in exclamations or calls, おや、太郎や.","ru":"や обозначает неполный перечень, 犬や猫（など）, а также встречается в восклицаниях и обращениях: おや、太郎や."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よい":{"b":"よい","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"い-sifətidir və いい ilə eynimənalıdır; よう bəzi ifadələrdə, məsələn おはよう-da görünən formadır.","en":"An い-adjective equivalent to いい; よう occurs in some expressions such as おはよう.","ru":"い-прилагательное, равнозначное いい; форма よう встречается в выражениях вроде おはよう."}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"わたし":{"b":"わたし (私)","p":"pr","m":{"az":"mən","en":"I, me","ru":"я"},"n":{"az":"Ən çox işlənən neytral 'mən'.","en":"The most common neutral 'I'.","ru":"Самое употребительное нейтральное 'я'."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ゴール":{"b":"ゴール","p":"n","m":{"az":"finiş, hədəf, qol","en":"finish line, goal","ru":"финиш, цель, гол"},"n":{"az":"Yarışda finişi, futbolda qolu bildirir.","en":"Means the finish line in a race or a goal in football.","ru":"Означает финиш в гонке или гол в футболе."}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"ソラさん":{"b":"ソラさん (そらさん)","p":"nm","m":{"az":"Sora (hörmətli müraciət)","en":"Sora (polite name)","ru":"Сора (вежливое обращение)"},"n":{"az":"さん ada əlavə edilən nəzakətli müraciət şəkilçisidir.","en":"さん is a polite suffix attached to a name.","ru":"さん - вежливый суффикс после имени."}},"バス":{"b":"バス","p":"n","m":{"az":"avtobus","en":"bus","ru":"автобус"}},"バトン":{"b":"バトン","p":"n","m":{"az":"estafet çubuğu","en":"relay baton","ru":"эстафетная палочка"}},"ホテル":{"b":"ホテル","p":"n","m":{"az":"otel, mehmanxana","en":"hotel","ru":"отель, гостиница"}},"ミナ":{"b":"ミナ","p":"nm","m":{"az":"Mina","en":"Mina","ru":"Мина"}},"ライバル":{"b":"ライバル","p":"n","m":{"az":"rəqib","en":"rival, competitor","ru":"соперник, конкурент"}},"リレー":{"b":"リレー","p":"n","m":{"az":"estafet yarışı","en":"relay race","ru":"эстафета"}},"レン":{"b":"レン","p":"nm","m":{"az":"Ren","en":"Ren","ru":"Рэн"}},"レンさん":{"b":"レンさん (れんさん)","p":"nm","m":{"az":"Ren (hörmətli müraciət)","en":"Ren (polite name)","ru":"Рэн (вежливое обращение)"},"n":{"az":"さん ada əlavə edilən nəzakətli müraciət şəkilçisidir.","en":"さん is a polite suffix attached to a name.","ru":"さん - вежливый суффикс после имени."}},"一":{"b":"一 (いち)","p":"nu","m":{"az":"bir","en":"one","ru":"один"}},"一本":{"b":"一本 (いっぽん)","p":"n","m":{"az":"bir dənə (uzun əşya)","en":"one (long thing)","ru":"одна штука (длинная)"},"n":{"az":"本 – uzun, nazik əşyalar üçün sayğac (bambuk, qələm, şüşə).","en":"本 – counter for long, thin things.","ru":"本 – счётный суффикс для длинных предметов."}},"一枚":{"b":"一枚 (いちまい)","p":"nu","m":{"az":"bir ədəd yastı əşya","en":"one flat object","ru":"один плоский предмет"},"n":{"az":"枚 kağız, şəkil və köynək kimi nazik, yastı əşyaları saymaq üçün işlənir.","en":"枚 counts thin, flat objects such as sheets of paper, pictures, and shirts.","ru":"枚 используется для счёта тонких плоских предметов, например листов бумаги, картинок и рубашек."}},"一番":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən; hamıdan çox","en":"most; best","ru":"самый; больше всего"},"n":{"az":"Sifətdən əvvəl üstünlük bildirir: 一番大きい = ən böyük; isim kimi «birinci yer» deməkdir.","en":"Before an adjective it marks the superlative: 一番大きい = biggest; as a noun it means first place.","ru":"Перед прилагательным выражает превосходную степень: 一番大きい = самый большой; как существительное означает первое место."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"三人":{"b":"三人 (さんにん)","p":"nu","m":{"az":"üç nəfər","en":"three people","ru":"три человека"},"n":{"az":"人 insan sayğacıdır: 一人 hitori, 二人 futari, 三人 sannin.","en":"人 counts people: 一人 hitori, 二人 futari, 三人 sannin.","ru":"人 считает людей: 一人 hitori, 二人 futari, 三人 sannin."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上げる":{"b":"上げる (あげる)","p":"v","m":{"az":"qaldırmaq, yüksəltmək","en":"to raise, to lift","ru":"поднимать, повышать"},"n":{"az":"Təsirli feldir; qarşılığı 上がる - qalxmaq.","en":"Transitive verb; its intransitive pair is 上がる.","ru":"Переходный глагол; непереходная пара - 上がる."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"二":{"b":"二 (に)","p":"nu","m":{"az":"iki","en":"two","ru":"два"}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"二匹":{"b":"二匹 (にひき)","p":"nu","m":{"az":"iki heyvan","en":"two small animals","ru":"два животных"},"n":{"az":"匹 kiçik heyvanları sayır, 二匹 にひき oxunur.","en":"匹 counts small animals, and 二匹 is pronounced にひき.","ru":"Счётный суффикс 匹 для небольших животных, 二匹 читается にひき."}},"二日目":{"b":"二日目 (ふつかめ)","p":"n","m":{"az":"ikinci gün","en":"second day","ru":"второй день"},"n":{"az":"二日 ふつか oxunur; 目 sıra bildirir.","en":"二日 is read ふつか; 目 indicates order.","ru":"二日 читается ふつか; 目 обозначает порядок."}},"二本":{"b":"二本 (にほん)","p":"nu","m":{"az":"iki ədəd uzun əşya","en":"two long objects","ru":"два длинных предмета"},"n":{"az":"本 sayğacı uzun əşyalar üçündür; 二本 にほん oxunur.","en":"本 counts long objects; 二本 is read にほん.","ru":"Счётчик 本 используется для длинных предметов; 二本 читается にほん."}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"今年":{"b":"今年 (ことし)","p":"n","m":{"az":"bu il","en":"this year","ru":"в этом году"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 今年行きます.","en":"Usually takes no に as a time expression: 今年行きます.","ru":"При обозначении времени обычно употребляется без に: 今年行きます."}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"会":{"b":"会 (かい)","p":"n","m":{"az":"toplantı, yığıncaq, tədbir","en":"meeting, gathering, event","ru":"собрание, встреча, мероприятие"}},"便利":{"b":"便利 (べんり)","p":"an","m":{"az":"rahat, əlverişli, faydalı","en":"convenient, useful","ru":"удобный, полезный"},"n":{"az":"な-sifətdir; isimdən əvvəl 便利な işlənir.","en":"A na-adjective; use 便利な before a noun.","ru":"Это na-прилагательное; перед существительным используется 便利な."}},"傘":{"b":"傘 (かさ)","p":"n","m":{"az":"çətir","en":"umbrella","ru":"зонт"}},"先":{"b":"先 (さき)","p":"n","m":{"az":"uc, son; qabaq","en":"end, tip; ahead","ru":"конец; впереди"},"n":{"az":"道の先 = yolun sonu.","en":"道の先 = the end of the path.","ru":"道の先 = конец дороги."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"写真":{"b":"写真 (しゃしん)","p":"n","m":{"az":"fotoşəkil","en":"photograph","ru":"фотография"}},"冷たい":{"b":"冷たい (つめたい)","p":"ai","m":{"az":"soyuq, soyuqqanlı","en":"cold, unfriendly","ru":"холодный, неприветливый"},"n":{"az":"い-sifətdir; əşyanın soyuqluğunu və ya insanın soyuq münasibətini bildirir.","en":"An i-adjective for something cold to the touch or an unfriendly attitude.","ru":"Прилагательное на い, обозначающее холод на ощупь или холодное отношение."}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"動物":{"b":"動物 (どうぶつ)","p":"n","m":{"az":"heyvan","en":"animal","ru":"животное"}},"午後":{"b":"午後 (ごご)","p":"n","m":{"az":"günün ikinci yarısı","en":"p.m.; afternoon","ru":"после полудня"},"n":{"az":"Saatla gecə vaxtını da bildirə bilər: 午後九時 = axşam saat doqquz.","en":"With clock times, it also covers evening: 午後九時 = 9 p.m.","ru":"Со временем обозначает и вечер: 午後九時 = девять часов вечера."}},"去年":{"b":"去年 (きょねん)","p":"n","m":{"az":"keçən il","en":"last year","ru":"в прошлом году"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 去年行きました.","en":"Usually takes no に as a time expression: 去年行きました.","ru":"При обозначении времени обычно употребляется без に: 去年行きました."}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"同じ":{"b":"同じ (おなじ)","p":"an","m":{"az":"eyni","en":"same","ru":"одинаковый, тот же"},"n":{"az":"İsimdən əvvəl な almır: 同じ月 = eyni Ay.","en":"Takes no な before a noun: 同じ月 = the same moon.","ru":"Перед сущ. без な: 同じ月 = та же луна."}},"周":{"b":"周 (しゅう)","p":"n","m":{"az":"dövrə, tam dövr","en":"lap, circuit","ru":"круг, оборот"},"n":{"az":"一周 いっしゅう bir tam dövrə deməkdir.","en":"一周 いっしゅう means one complete lap.","ru":"一周 いっしゅう означает один полный круг."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"場所":{"b":"場所 (ばしょ)","p":"n","m":{"az":"yer","en":"place","ru":"место"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"天気":{"b":"天気 (てんき)","p":"n","m":{"az":"hava, hava şəraiti","en":"weather","ru":"погода"}},"太い":{"b":"太い (ふとい)","p":"ai","m":{"az":"qalın, yoğun","en":"thick, stout","ru":"толстый"},"n":{"az":"い-sifətdir; 太くて bağlayıcı formasıdır.","en":"An i-adjective; 太くて is its connecting form.","ru":"Это i-прилагательное; 太くて - соединительная форма."}},"好き":{"b":"好き (すき)","p":"an","m":{"az":"sevimli; sevmək","en":"liked; to like","ru":"любимый; нравиться"},"n":{"az":"N が好きです = N-i sevirəm. Yaponcada 'sevmək' sifətlə deyilir.","en":"N が好きです = I like N. 'To like' is an adjective in Japanese.","ru":"N が好きです = мне нравится N. 'Нравиться' – прилагательное."}},"始まる":{"b":"始まる (はじまる)","p":"v","m":{"az":"başlamaq","en":"to begin; to start","ru":"начинаться"},"n":{"az":"Təsirsizdir: 祭りが始まります; təsirli qarşılığı 始める-dir.","en":"Intransitive: 祭りが始まります; its transitive partner is 始める.","ru":"Непереходный: 祭りが始まります; переходная пара: 始める."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"寂しい":{"b":"寂しい (さびしい)","p":"ai","m":{"az":"tənha, kədərli, darıxmış","en":"lonely, sad","ru":"одинокий, тоскливый"},"n":{"az":"い-sifətdir; 寂しく forması zərf kimi və ya başqa quruluşlarda işlənir.","en":"An i-adjective; 寂しく is used adverbially or in other constructions.","ru":"Это i-прилагательное; 寂しく используется как наречие или в других конструкциях."}},"寝る":{"b":"寝る (ねる)","p":"v","m":{"az":"yatmaq; yuxuya getmək","en":"to sleep; to go to bed","ru":"спать; ложиться спать"},"n":{"az":"寝ていました = yatırdı.","en":"寝ていました means was sleeping.","ru":"寝ていました означает «спал»."}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"帰り":{"b":"帰り (かえり)","p":"n","m":{"az":"qayıdış; geri yol","en":"return; way back","ru":"возвращение; обратный путь"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"心":{"b":"心 (こころ)","p":"n","m":{"az":"ürək, qəlb, könül","en":"heart, mind, spirit","ru":"сердце, душа, разум"},"n":{"az":"Burada fiziki orqandan çox hiss və düşüncəni bildirir.","en":"Usually refers to feelings or the mind rather than the physical organ.","ru":"Обычно обозначает чувства или душу, а не физический орган."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"所":{"b":"所 (ところ)","p":"n","m":{"az":"yer, məkan","en":"place, spot","ru":"место"}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"拍手":{"b":"拍手 (はくしゅ)","p":"n","m":{"az":"alqış","en":"applause, clapping","ru":"аплодисменты"},"n":{"az":"拍手する - alqışlamaq.","en":"拍手する means to clap or applaud.","ru":"拍手する означает аплодировать."}},"指す":{"b":"指す (さす)","p":"v","m":{"az":"göstərmək; işarə etmək","en":"point to; indicate","ru":"указывать; показывать"},"n":{"az":"指で指す barmaqla göstərməkdir; saatın əqrəbi də vaxtı 指す ilə göstərir.","en":"指で指す means to point with a finger; clock hands also 指す a time.","ru":"指で指す означает указывать пальцем; стрелки часов также показывают время с 指す."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"旅行":{"b":"旅行 (りょこう)","p":"n","m":{"az":"səyahət","en":"travel; trip","ru":"путешествие; поездка"},"n":{"az":"旅行する = səyahət etmək; 旅行に行く = səyahətə getmək.","en":"旅行する means to travel; 旅行に行く means to go on a trip.","ru":"旅行する означает путешествовать; 旅行に行く означает отправляться в поездку."}},"旗":{"b":"旗 (はた)","p":"n","m":{"az":"bayraq","en":"flag","ru":"флаг"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日曜":{"b":"日曜 (にちよう)","p":"n","m":{"az":"bazar günü","en":"Sunday","ru":"воскресенье"}},"早い":{"b":"早い (はやい)","p":"ai","m":{"az":"erkən; tez","en":"early","ru":"ранний; рано"},"n":{"az":"い-sifətidir; 早く zərf formasıdır, sürət mənasında isə 速い yazılır.","en":"An い-adjective; 早く is its adverb form, while 速い refers to speed.","ru":"い-прилагательное; 早く является наречной формой, а 速い обозначает скорость."}},"春":{"b":"春 (はる)","p":"n","m":{"az":"yaz (fəsil)","en":"spring","ru":"весна"}},"昼":{"b":"昼 (ひる)","p":"n","m":{"az":"günorta; gündüz","en":"noon; daytime","ru":"полдень; дневное время"}},"昼寝":{"b":"昼寝 (ひるね)","p":"n","m":{"az":"gündüz yuxusu, mürgü","en":"nap, daytime sleep","ru":"дневной сон"},"n":{"az":"昼寝する - gündüz yatmaq.","en":"昼寝する means to take a nap.","ru":"昼寝する означает вздремнуть днём."}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"晴れ":{"b":"晴れ (はれ)","p":"n","m":{"az":"açıq, günəşli hava","en":"clear weather, sunshine","ru":"ясная, солнечная погода"}},"暇":{"b":"暇 (ひま)","p":"an","m":{"az":"boş vaxt, boş, məşğul olmayan","en":"free time, free, unoccupied","ru":"свободное время, свободный"},"n":{"az":"な-sifət kimi 暇な人, isim kimi 暇がある işlənir.","en":"Used as a na-adjective in 暇な人 or as a noun in 暇がある.","ru":"Употребляется как na-прилагательное в 暇な人 или как существительное в 暇がある."}},"暑い":{"b":"暑い (あつい)","p":"ai","m":{"az":"isti (hava haqqında)","en":"hot (weather)","ru":"жаркий (о погоде)"},"n":{"az":"い-sifətdir; 暑かった keçmiş zaman formasıdır.","en":"An i-adjective; 暑かった is its past form.","ru":"Это i-прилагательное; 暑かった - форма прошедшего времени."}},"暖かい":{"b":"暖かい (あたたかい)","p":"ai","m":{"az":"isti, ilıq","en":"warm","ru":"тёплый"},"n":{"az":"İ-sifətidir; əsasən hava və mühitin istiliyini, 温かい isə əşya, yemək və münasibətin istiliyini bildirir.","en":"An i-adjective mainly describing warm weather or surroundings; 温かい is used for objects, food, and personal warmth.","ru":"Прилагательное на い, обычно о тёплой погоде или обстановке; 温かい употребляется о предметах, еде и душевном тепле."}},"曇り":{"b":"曇り (くもり)","p":"n","m":{"az":"buludlu hava","en":"cloudy weather","ru":"облачная погода"}},"最後":{"b":"最後 (さいご)","p":"n","m":{"az":"son, axır","en":"end, last","ru":"конец, последний"}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"朝ご飯":{"b":"朝ご飯 (あさごはん)","p":"n","m":{"az":"səhər yeməyi","en":"breakfast","ru":"завтрак"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"校庭":{"b":"校庭 (こうてい)","p":"n","m":{"az":"məktəb həyəti, məktəb meydançası","en":"schoolyard, school playground","ru":"школьный двор, школьная площадка"}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"横":{"b":"横 (よこ)","p":"n","m":{"az":"yan; böyür","en":"side; beside","ru":"бок; рядом"},"n":{"az":"Nの横 = N-in yanı; üfüqi istiqamət mənası da var.","en":"Nの横 means beside N; 横 can also refer to a horizontal direction.","ru":"Nの横 означает рядом с N; 横 также обозначает горизонтальное направление."}},"歩":{"b":"歩 (ほ)","p":"nu","m":{"az":"addım","en":"step, pace","ru":"шаг"},"n":{"az":"Addım sayğacı kimi 一歩 いっぽ, 二歩 にほ, 三歩 さんぽ deyilir.","en":"As a step counter: 一歩 いっぽ, 二歩 にほ, 三歩 さんぽ.","ru":"Как счётчик шагов: 一歩 いっぽ, 二歩 にほ, 三歩 さんぽ."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"泊":{"b":"泊 (はく)","p":"nu","m":{"az":"gecələmə, gecəlik qalma","en":"overnight stay, night","ru":"ночёвка, ночь проживания"},"n":{"az":"Gecələmə sayğacıdır; 一泊 いっぱく, 二泊 にはく deyilir.","en":"Counts overnight stays; 一泊 is いっぱく and 二泊 is にはく.","ru":"Считает ночёвки; 一泊 читается いっぱく, 二泊 - にはく."}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"涼しい":{"b":"涼しい (すずしい)","p":"ai","m":{"az":"sərin, xoş sərinlikdə","en":"cool, pleasantly cool","ru":"прохладный"},"n":{"az":"い-sifətdir; xoş sərinliyi bildirir, soyuq mənasındakı 寒い ilə eyni deyil.","en":"An i-adjective for pleasant coolness, unlike 寒い, which means cold.","ru":"Это i-прилагательное для приятной прохлады, в отличие от 寒い - холодный."}},"狭い":{"b":"狭い (せまい)","p":"ai","m":{"az":"dar, kiçik sahəli","en":"narrow, cramped","ru":"узкий, тесный"},"n":{"az":"い-sifətdir; əksi 広い - geniş.","en":"An i-adjective; its opposite is 広い, spacious.","ru":"Это i-прилагательное; антоним 広い - просторный."}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"白組":{"b":"白組 (しろぐみ)","p":"n","m":{"az":"ağ komanda","en":"white team","ru":"белая команда"},"n":{"az":"Məktəb yarışlarında ağ rəngli komandanı bildirir.","en":"Refers to the white team in school competitions.","ru":"Обозначает белую команду на школьных соревнованиях."}},"石":{"b":"石 (いし)","p":"n","m":{"az":"daş","en":"stone, rock","ru":"камень"}},"秋":{"b":"秋 (あき)","p":"n","m":{"az":"payız","en":"autumn, fall","ru":"осень"}},"空港":{"b":"空港 (くうこう)","p":"n","m":{"az":"hava limanı","en":"airport","ru":"аэропорт"}},"競走":{"b":"競走 (きょうそう)","p":"n","m":{"az":"qaçış yarışı, sürət yarışı","en":"race, running competition","ru":"гонка, соревнование в беге"},"n":{"az":"競走する yarışmaq deməkdir; 競争 isə ümumi rəqabət mənasında işlənir.","en":"競走 refers to racing, while 競争 means competition more generally.","ru":"競走 означает гонку, а 競争 - соревнование или конкуренцию в общем смысле."}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答え":{"b":"答え (こたえ)","p":"n","m":{"az":"cavab","en":"answer","ru":"ответ"}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"細い":{"b":"細い (ほそい)","p":"ai","m":{"az":"nazik, incə","en":"thin, slender","ru":"тонкий, узкий"},"n":{"az":"い-sifətidir; uzun və nazik əşyalar üçün işlənir, yastı əşyaların nazikliyi isə 薄い ilə ifadə olunur.","en":"This is an い-adjective for slender objects; 薄い describes thin flat objects.","ru":"Это прилагательное на い для тонких вытянутых предметов; малая толщина плоских предметов передаётся словом 薄い."}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"赤組":{"b":"赤組 (あかぐみ)","p":"n","m":{"az":"qırmızı komanda","en":"red team","ru":"красная команда"},"n":{"az":"Məktəb yarışlarında qırmızı rəngli komandanı bildirir.","en":"Refers to the red team in school competitions.","ru":"Обозначает красную команду на школьных соревнованиях."}},"走者":{"b":"走者 (そうしゃ)","p":"n","m":{"az":"qaçışçı, yarış iştirakçısı","en":"runner, racer","ru":"бегун, участник забега"}},"起きる":{"b":"起きる (おきる)","p":"v","m":{"az":"oyanmaq; yataqdan qalxmaq","en":"to wake up; to get up","ru":"просыпаться; вставать"},"n":{"az":"Təsirsizdir; 起こす kimisə oyatmaq deməkdir.","en":"Intransitive; 起こす means to wake someone up.","ru":"Непереходный; 起こす означает будить кого-то."}},"足":{"b":"足 (あし)","p":"n","m":{"az":"ayaq","en":"foot; leg","ru":"нога; ступня"},"n":{"az":"Kontekstdən asılı olaraq ayağın pəncəsini və ya bütün aşağı ətrafı bildirir.","en":"Can mean the foot or the whole leg, depending on context.","ru":"В зависимости от контекста обозначает ступню или всю ногу."}},"転ぶ":{"b":"転ぶ (ころぶ)","p":"v","m":{"az":"yıxılmaq, büdrəyib yıxılmaq","en":"to fall down, to tumble","ru":"падать, спотыкаться и падать"},"n":{"az":"Təsirsiz feldir; 転びました nəzakətli keçmiş zaman formasıdır.","en":"An intransitive verb; 転びました is its polite past form.","ru":"Непереходный глагол; 転びました - вежливая форма прошедшего времени."}},"軽い":{"b":"軽い (かるい)","p":"ai","m":{"az":"yüngül","en":"light, lightweight","ru":"лёгкий"},"n":{"az":"い-sifətdir; əksi 重い - ağır.","en":"An i-adjective; its opposite is 重い, heavy.","ru":"Это i-прилагательное; антоним 重い - тяжёлый."}},"近い":{"b":"近い (ちかい)","p":"ai","m":{"az":"yaxın","en":"near, close","ru":"близкий"},"n":{"az":"い-sifətdir; 〜に近い - bir yerə və ya şeyə yaxın.","en":"An i-adjective; 〜に近い means close to something.","ru":"Это i-прилагательное; 〜に近い означает близко к чему-либо."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"速い":{"b":"速い (はやい)","p":"ai","m":{"az":"sürətli, cəld","en":"fast, quick","ru":"быстрый, скорый"},"n":{"az":"い-sifətdir: 速くて = sürətli olub; 速い sürəti, 早い isə erkən vaxtı bildirir.","en":"An i-adjective: 速くて connects descriptions; 速い means fast, while 早い means early.","ru":"Прилагательное на い: 速くて соединяет описания; 速い означает быстрый, а 早い означает ранний."}},"進む":{"b":"進む (すすむ)","p":"v","m":{"az":"irəliləmək, davam etmək","en":"to advance, to move forward","ru":"продвигаться, двигаться вперёд"},"n":{"az":"Təsirsiz feldir; təsirli qarşılığı 進める - irəli aparmaq.","en":"An intransitive verb; the transitive pair is 進める.","ru":"Непереходный глагол; переходная пара - 進める."}},"遅い":{"b":"遅い (おそい)","p":"ai","m":{"az":"gec; yavaş","en":"late; slow","ru":"поздний; медленный"},"n":{"az":"い-sifətidir; vaxta görə «gec», sürətə görə «yavaş» deməkdir.","en":"An い-adjective meaning late for time and slow for speed.","ru":"い-прилагательное: для времени означает «поздний», для скорости «медленный»."}},"運動":{"b":"運動 (うんどう)","p":"n","m":{"az":"idman, fiziki hərəkət, məşq","en":"exercise, physical activity","ru":"физические упражнения, спорт"},"n":{"az":"運動する - idman etmək və ya fiziki məşq etmək.","en":"運動する means to exercise or do physical activity.","ru":"運動する означает заниматься физическими упражнениями."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"違う":{"b":"違う (ちがう)","p":"v","m":{"az":"fərqlənmək; səhv olmaq","en":"differ; be wrong","ru":"отличаться; быть неверным"},"n":{"az":"Sifət deyil, feldir; 違います cavabı bu belə deyil və ya səhvdir mənasını verə bilər.","en":"A verb, not an adjective; 違います can mean that is not so or that is wrong.","ru":"Это глагол, не прилагательное; ответ 違います может означать это не так или это неверно."}},"遠く":{"b":"遠く (とおく)","p":"n","m":{"az":"uzaq yer, uzaqlıq","en":"faraway place, distance","ru":"далёкое место, даль"},"n":{"az":"遠い sifətinin formasıdır; 遠くに uzaqda deməkdir.","en":"Derived from 遠い; 遠くに means far away.","ru":"Образовано от 遠い; 遠くに означает далеко."}},"選ぶ":{"b":"選ぶ (えらぶ)","p":"v","m":{"az":"seçmək","en":"to choose, to select","ru":"выбирать"},"n":{"az":"〜を選ぶ - nəyisə seçmək; 選びました keçmiş zamandır.","en":"〜を選ぶ means to choose something; 選びました is past tense.","ru":"〜を選ぶ означает выбирать что-либо; 選びました - прошедшее время."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"重さ":{"b":"重さ (おもさ)","p":"n","m":{"az":"çəki, ağırlıq","en":"weight, heaviness","ru":"вес, тяжесть"},"n":{"az":"重い sifətindən さ ilə düzəlmiş isimdir.","en":"A noun formed from the adjective 重い with the suffix さ.","ru":"Существительное, образованное от прилагательного 重い с помощью суффикса さ."}},"隣":{"b":"隣 (となり)","p":"n","m":{"az":"yan, qonşuluq","en":"next door, next to","ru":"соседство, рядом"},"n":{"az":"Nの隣 birbaşa N-in yanındakı yeri bildirir.","en":"Nの隣 refers to a place directly next to N.","ru":"Nの隣 обозначает место непосредственно рядом с N."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"首":{"b":"首 (くび)","p":"n","m":{"az":"boyun; baş","en":"neck; head","ru":"шея; голова"},"n":{"az":"首をふる = başını bulamaq (inkar).","en":"首をふる = shake one's head.","ru":"首をふる = покачать головой."}},"鳥":{"b":"鳥 (とり)","p":"n","m":{"az":"quş","en":"bird","ru":"птица"}}}};